{{ config(
            materialized='table',
                post_hook={
                    "sql": "DROP TABLE IF EXISTS public.Tuco_Kids_flipkart_order_fulfilment_fact_items; CREATE TABLE public.Tuco_Kids_flipkart_order_fulfilment_fact_items AS SELECT CAST(order_date AS DATE) AS order_date, CAST(NULLIF(REPLACE(order_approval_date, \'\"\', \'\'), \'\') AS DATE) AS order_approval_date, REPLACE(REPLACE(sku, \'\"\', \'\'), \'sku:\', \'\') AS sku, order_id AS reference_code, order_id, CAST(NULLIF(order_cancellation_date, \'\') AS TIMESTAMP) AS cancellation_date, REPLACE(cancellation_reason,\'_\',\' \') AS cancellation_reason, CAST(NULLIF(order_ready_for_dispatch_on_date, \'\') AS TIMESTAMP) AS order_ready_for_dispatch_on_date, CAST(NULLIF(dispatch_after_date, \'\') AS TIMESTAMP) AS manifest_date, CAST(NULLIF(dispatch_by_date, \'\') AS TIMESTAMP) AS dispatch_date, CASE WHEN deliver_by_date = \'N\' THEN NULL ELSE CAST(deliver_by_date AS DATE) END AS delivery_date, CASE WHEN UPPER(pickup_logistics_partner) LIKE \'%cod%\' THEN \'cod\' ELSE \'prepaid\' END AS payment_mode, pickup_logistics_partner as courier, CAST(NULLIF(order_return_approval_date, \'\') AS date) AS return_approval_date, CAST(NULLIF(order_service_completion_date, \'\') AS date) AS order_service_completion_date, return_id, REPLACE(return_reason,\'_\',\' \') AS return_reason, REPLACE(return_sub_reason,\'_\',\' \') AS return_sub_reason, REPLACE(order_item_id,\'OI:\',\'\') AS order_item_id, REPLACE(product_title, \'\"\', \'\') AS product_name, fulfilment_type, fulfilment_source, REPLACE(order_item_status,\'_\',\' \') AS order_item_status, REPLACE(delivery_tracking_id, \'DTr:\', \'\') AS fk_awb FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, order_item_id ORDER BY order_return_approval_date DESC) AS rn FROM public.Flipkart_Tuco_Kids_orders ) x WHERE rn = 1; DROP TABLE IF EXISTS public.Tuco_Kids_flipkart_fact_items_intermediate; CREATE TABLE public.Tuco_Kids_flipkart_fact_items_intermediate AS SELECT CASE WHEN s.\"Fulfilment Type\" = \'NON_FBF\' THEN \'Flipkart deodap NON-FBF\' ELSE \'Flipkart deodap FBF\' END AS shop_name, s.\"order id\", s.\"order id\" AS order_name, NULL AS customer_id, NULL AS phone, \"hsn code\" as HSN_Code, s.\"order type\" AS payment_type, CAST(NULL AS VARCHAR) AS tags, s.\"order item id\" AS line_item_id, CAST(REPLACE(REPLACE(s.sku,\'\"\',\'\'),\'SKU:\',\'\') AS VARCHAR) AS SKU, REPLACE(s.FSN,\'\"\',\'\') AS product_id, CASE WHEN s.\"Event Sub Type\" = \'Return\' THEN 1 ELSE 0 END AS is_refund, CAST(NULL AS VARCHAR) AS city, CASE WHEN s.\"customer\'s delivery state\" = \'-\' THEN (CASE WHEN s.\"customer\'s billing state\" = \'-\' THEN NULL ELSE s.\"customer\'s billing state\" END) ELSE s.\"customer\'s delivery state\" END AS state, CASE WHEN s.\"customer\'s delivery pincode\" = \'-\' THEN (CASE WHEN s.\"customer\'s billing pincode\" = \'-\' THEN NULL ELSE s.\"customer\'s billing pincode\" END) ELSE s.\"customer\'s delivery pincode\" END AS pincode, REPLACE(\"product title/description\",\'\"\',\'\') AS PRODUCT_NAME, CAST(NULL AS VARCHAR) AS category, f.order_date, f.delivery_date, f.cancellation_date, f.manifest_date, f.dispatch_date, f.return_approval_date, f.return_reason, f.return_sub_reason, f.order_service_completion_date, f.order_item_status, f.return_id, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, CAST(\"tds rate\" AS DOUBLE PRECISION) AS tds_rate, CAST(\"VAT Rate\" AS DOUBLE PRECISION) AS VAT_Rate, CAST(\"CGST Rate\" AS DOUBLE PRECISION) AS CGST_Rate, CAST(\"IGST Rate\" AS DOUBLE PRECISION) AS IGST_Rate, CAST(\"CST Amount\" AS DOUBLE PRECISION) AS CST_Amount, CAST(\"TDS Amount\" AS DOUBLE PRECISION) AS TDS_Amount, CAST(\"VAT Amount\" AS DOUBLE PRECISION) AS VAT_Amount, CAST(\"CGST Amount\" AS DOUBLE PRECISION) AS CGST_Amount, CAST(\"IGST Amount\" AS DOUBLE PRECISION) AS IGST_Amount, CAST(\"Type of tax\" AS DOUBLE PRECISION) AS Type_of_tax, CASE WHEN \"Usual Price\" = \'NA\' THEN NULL ELSE CAST(\"Usual Price\" AS DOUBLE PRECISION) END AS Usual_Price, \"Seller GSTIN\", ABS(COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0)) AS line_item_sales, ABS(COALESCE(CAST(\"Shipping Charges\" AS DOUBLE PRECISION), 0)) AS shipping_price, ABS(COALESCE(CAST(\"Item Quantity\" AS DOUBLE PRECISION), 0)) AS quantity, ABS(COALESCE(CAST(\"Total TCS Deducted\" AS DOUBLE PRECISION), 0)) AS tax, ABS(COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0)) / NULLIF( COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0) + COALESCE(CAST(\"Total TCS Deducted\" AS DOUBLE PRECISION), 0), 0) AS overall_tax_rate, ABS(COALESCE(CAST(\"Total Discount\" AS DOUBLE PRECISION), 0)) AS discount, ABS(COALESCE(CAST(\"Total Discount\" AS DOUBLE PRECISION), 0)) / NULLIF( 1 - (ABS(COALESCE(CAST(\"Total TCS Deducted\" AS DOUBLE PRECISION), 0)) / NULLIF( ABS(COALESCE(CAST(\"Total TCS Deducted\" AS DOUBLE PRECISION), 0)) + ABS(COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0)), 0)), 0) AS discount_before_tax, (ABS(COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0)) - ABS(COALESCE(CAST(\"Total Discount\" AS DOUBLE PRECISION), 0)) / NULLIF( 1 - (ABS(COALESCE(CAST(\"Total TCS Deducted\" AS DOUBLE PRECISION), 0)) / NULLIF( ABS(COALESCE(CAST(\"Total TCS Deducted\" AS DOUBLE PRECISION), 0)) + ABS(COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0)), 0)), 0)) AS gross_sales_before_tax, ABS(COALESCE(CAST(\"price after discount (price before discount-total discount)\" AS DOUBLE PRECISION), 0)) AS total_sales, CASE WHEN LOWER(\"is shopsy order?\") IN (\'true\', \'1\', \'yes\', \'y\') THEN \'Shopsy Order\' ELSE \'Flipkart Order\' END AS Order_Channel, \"Beneficiary Name\" AS name, CAST(NULL AS VARCHAR) AS email, fk_awb as awb, courier, \"order shipped from (state)\" AS Order_Shipped_From_State, \"Warehouse ID\", \"Business Name\" FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY \"order item id\", \"order id\" ORDER BY \"buyer invoice id\" DESC) AS rn FROM public.Flipkart_Tuco_Kids_sales ) s LEFT JOIN public.Tuco_Kids_flipkart_order_fulfilment_fact_items f ON f.order_id = s.\"order id\" AND f.order_item_id = s.\"order item id\" WHERE s.rn = 1 ; DROP TABLE IF EXISTS public.Tuco_Kids_flipkart_fact_items; CREATE TABLE public.Tuco_Kids_flipkart_fact_items AS select fi.* ,COALESCE(UPPER(sm.product_name),UPPER(fi.product_name)) AS product_name_final ,UPPER(sm.color) AS Color ,UPPER(sm.size) AS Size ,UPPER(sm.commonsku) as commonsku from public.Tuco_Kids_flipkart_fact_items_intermediate fi left join (select * from (select product_name, color, size, marketplace_sku, marketplace_id, marketplace, commonsku, CATEGORY, ROW_NUMBER() OVER (PARTITION BY REPLACE(CAST(marketplace_sku AS VARCHAR), \' \', \'\') ORDER BY LENGTH(COALESCE(CAST(marketplace_sku AS VARCHAR), \'\')) DESC) AS rw FROM public.tuco_kids_final_sku_master where lower(marketplace) like \'%flipkart%\' ) WHERE rw = 1 ) sm ON LOWER(REPLACE(CAST(fi.product_id AS VARCHAR), \' \', \'\')) = LOWER(REPLACE(CAST(sm.marketplace_sku AS VARCHAR), \' \', \'\')) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

